// 1930s HOLC redlining, set against SVI 2022. Data: holc.js (generated by
// tools/build_holc.py) and the georectified HOLC scans from Mapping
// Inequality (University of Richmond DSL, CC BY-NC).
//
// Three ways to compare "then" with "now":
//
//   Swipe          one map; drag the bar. Left: SVI. Right: 1930s.
//   +-----------|-----------+
//   |  SVI now  |  1930s    |   same streets, same place
//   +-----------|-----------+
//
//   Side by side   two maps, locked together; a ring marks the
//                  cursor's spot on the other map.
//   Overlay        1930s layer on top of SVI, opacity slider.
//
// Swipe is the default: lining things up in one frame beats reading two
// maps from memory (Gleicher et al. 2011, "Visual comparison for
// information visualization"; swipe and juxtaposition studies of map
// change). Grades draw as outlines in Overlay so colors don't blend.
(function(){
var map = map_81f614882c315cc8a20dc059629ce4e3;

// Mapping Inequality's grade colors, so the map reads like theirs.
var HOLC_COL = {A:'#76a865', B:'#7cb5bd', C:'#ffff00', D:'#d9838d'};
var HOLC_EDGE = {A:'#3d6b30', B:'#3f7c86', C:'#a3a300', D:'#b0303f'};
var HOLC_NAME = {A:'Best', B:'Still desirable', C:'Definitely declining', D:'Hazardous (redlined)'};

// Georectified scans: s3.amazonaws.com/holc/tiles/<st>/<file>/<year>/.
var SCANS = [
  ['MI','Detroit','1939',5,14,[[41.98725,-83.49385],[42.64341,-82.76121]]],
  ['MI','Pontiac','1937',8,16,[[42.59433,-83.34224],[42.69058,-83.238]]],
  ['GA','Atlanta','1938',7,16,[[33.68787,-84.48753],[33.8539,-84.24094]]],
  ['GA','AtlantaInset','1938',8,15,[[33.83693,-84.46209],[33.87995,-84.29854]]],
  ['GA','AtlantaInset2','1938',9,15,[[33.63597,-84.46406],[33.69934,-84.42496]]]
];
var CITE = 'HOLC maps: <a href="https://dsl.richmond.edu/panorama/redlining/" target="_blank" rel="noopener">Mapping Inequality</a> (Nelson, Winling et al.), CC BY-NC';

// A tract counts once a fifth of it was graded (matches build_holc.py).
var MIN_COVER = 0.2;

var PAST = 'past';
var MODE = {OFF:'off', SWIPE:'swipe', SIDE:'side', OVER:'over'};
var VIEW = {SCAN:'scan', AREA:'area', TRACT:'tract'};
var WIDE = 700;

function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }

// Grade band for a historic redlining score (1 = all A, 4 = all D).
function hrsGrade(h){
  if(h < 1.75){ return 'A'; }
  if(h < 2.5){ return 'B'; }
  if(h < 3.25){ return 'C'; }
  return 'D';
}

// --- Popups -----------------------------------------------------------

// Area description fields, in reading order, with plain labels.
var AD = [['date','Surveyed'],['occ','Residents (occupation, class)'],['income','Family income'],
  ['foreign','Foreign-born (%, origin)'],['negro','Black residents (%)'],['infil','"Infiltration of"'],
  ['relief','Families on relief'],['fav','Favorable'],['det','Detrimental'],['trend','Trend'],
  ['mort','Mortgage money'],['remarks','Remarks']];

function areaHtml(p){
  var h = '<b style="color:'+HOLC_EDGE[p.g]+'">'+p.g+' &middot; '+HOLC_NAME[p.g]+'</b><br><b>'+esc(p.c)+' '+esc(p.l)+(p.n?' &mdash; '+esc(p.n):'')+'</b>';
  AD.forEach(function(f){
    if(!p[f[0]]){ return; }
    h += '<div style="margin-top:3px"><small style="color:#555">'+f[1]+'</small><br>'+esc(p[f[0]])+'</div>';
  });
  h += '<div style="margin-top:6px"><a href="'+p.u+'" target="_blank" rel="noopener">Original form and scan (Mapping Inequality)</a></div>';
  h += '<small style="color:#555">1930s appraisers\' words, kept as written.</small>';
  return h;
}

function tractHtml(id){
  var d = window.SVI.DATA[id];
  var h = '<b>'+(d ? esc(d.n) : id)+'</b><br>'+window.SVI.holcLine(id);
  if(d && d.r !== undefined){ h += '<br>SVI 2022: <b>'+d.r.toFixed(3)+'</b>'; }
  return h;
}


// --- Hover tip --------------------------------------------------------
// In compare modes the full SVI popup covers what you are comparing, so
// hovering shows one short line instead; click still opens the popup.

var tip = document.createElement('div');
tip.id = 'holc-tip';
document.body.appendChild(tip);
document.addEventListener('mousemove', function(e){
  tip.style.left = (e.clientX + 14) + 'px';
  tip.style.top = (e.clientY + 14) + 'px';
});

function gradesShort(id){
  var t = HOLC_TRACT[id];
  if(!t || t[0] < MIN_COVER){ return '1930s: not graded'; }
  return '1930s: ' + ['A','B','C','D'].map(function(g,i){ return t[2+i] >= 0.05 ? g+' '+Math.round(t[2+i]*100)+'%' : null; }).filter(Boolean).join(', ');
}

function tractTip(id){
  var d = window.SVI.DATA[id];
  if(!d){ return ''; }
  var svi = d.r === undefined ? 'no SVI' : 'SVI <b>'+d.r.toFixed(2)+'</b>';
  return esc(d.n.replace('Census ', ''))+' &middot; '+svi+' &middot; '+gradesShort(id);
}

function areaTip(p){
  return '<b style="color:'+HOLC_EDGE[p.g]+'">'+p.g+'</b> '+esc(p.c)+' '+esc(p.l)+(p.n ? ' &middot; '+esc(p.n) : '');
}

function tipOn(l, html){
  l.on('mouseover', function(){
    if(!window.SVI.quiet){ return; }
    tip.innerHTML = html(); tip.style.display = 'block';
  });
  l.on('mouseout', function(){ tip.style.display = 'none'; });
}

// Every tract shape in the SVI overlays gets the tip.
function tipAll(l){
  if(l.eachLayer && !l.feature){ l.eachLayer(tipAll); return; }
  if(!l.feature){ return; }
  var id = l.feature.properties.GEOID || l.feature.id;
  tipOn(l, function(){ return tractTip(id); });
}
var ov = layer_control_097befece45624d0ea761f79e99176c6_layers.overlays;
for(var k in ov){ tipAll(ov[k]); }

// --- Layers (factories: Side by side needs a second copy) --------------

function scanLayer(pane){
  return L.layerGroup(SCANS.map(function(s){
    return L.tileLayer('https://s3.amazonaws.com/holc/tiles/'+s[0]+'/'+s[1]+'/'+s[2]+'/{z}/{x}/{y}.png',
      {minZoom:s[3], maxNativeZoom:s[4], maxZoom:19, bounds:s[5], pane:pane, attribution:CITE});
  }));
}

function areaLayer(pane, outline){
  return L.geoJson(HOLC_AREAS, {pane:pane, renderer:L.svg({pane:pane}),
    style:function(f){ var g=f.properties.g;
      return outline ? {color:HOLC_EDGE[g], weight:3, fillColor:HOLC_COL[g], fillOpacity:0, opacity:1}
                     : {color:HOLC_EDGE[g], weight:1, fillColor:HOLC_COL[g], fillOpacity:0.75, opacity:1}; },
    onEachFeature:function(f,l){ l.bindPopup(areaHtml(f.properties), {maxWidth:320, maxHeight:Math.round(window.innerHeight*0.6)});
      tipOn(l, function(){ return areaTip(f.properties); }); },
    attribution:CITE});
}

// Tract redlining score in the same tract shapes SVI uses: the most
// direct comparison, since both sides then share one geography.
function tractLayer(pane){
  var src = [EXTRA_GEO];
  var dk = {type:'FeatureCollection', features:[]};
  geo_json_bf9a23d19065cc6d2d806ecafd7be546.eachLayer(function(l){ dk.features.push(l.feature); });
  src.push(dk);

  var g = L.featureGroup();
  src.forEach(function(fc){
    L.geoJson(fc, {pane:pane, renderer:L.svg({pane:pane}),
      filter:function(f){ var t=HOLC_TRACT[f.properties.GEOID||f.id]; return t && t[0] >= MIN_COVER; },
      style:function(f){ var t=HOLC_TRACT[f.properties.GEOID||f.id], k=hrsGrade(t[1]);
        return {fillColor:HOLC_COL[k], fillOpacity:0.8, color:'white', weight:0.5}; },
      onEachFeature:function(f,l){ var id=f.properties.GEOID||f.id; l.bindPopup(tractHtml(id), {maxWidth:300});
        tipOn(l, function(){ return tractTip(id); }); },
      attribution:CITE}).addTo(g);
  });
  return g;
}

function pastLayer(view, pane, outline){
  if(view === VIEW.SCAN){ return scanLayer(pane); }
  if(view === VIEW.TRACT){ return tractLayer(pane); }
  return areaLayer(pane, outline);
}

map.createPane(PAST).style.zIndex = 420;

// --- Swipe ------------------------------------------------------------

var bar = L.DomUtil.create('div', 'swipe-bar', map.getContainer());
bar.innerHTML = '<div class="swipe-knob" title="Drag">&#x2039;&#x203A;</div><span class="swipe-l">SVI 2022</span><span class="swipe-r">1930s HOLC</span>';
L.DomEvent.disableClickPropagation(bar);
var swipeX = 0.5;

// Clip a pane to one side of the bar, in layer coordinates (panes move
// with the map, so the clip is redone on every move).
function clipPane(name, side){
  var el = map.getPane(name);
  if(side === null){ el.style.clip = ''; return; }
  var size = map.getSize();
  var nw = map.containerPointToLayerPoint([0,0]), se = map.containerPointToLayerPoint(size);
  var x = nw.x + size.x * swipeX;
  el.style.clip = side === 'left'
    ? 'rect('+[nw.y, x, se.y, nw.x].join('px,')+'px)'
    : 'rect('+[nw.y, se.x, se.y, x].join('px,')+'px)';
}

function swipeUpdate(){
  if(state.mode !== MODE.SWIPE){ return; }
  bar.style.left = (swipeX*100)+'%';
  clipPane('overlayPane', 'left');
  clipPane(PAST, 'right');
}

L.DomEvent.on(bar, 'pointerdown', function(e){
  bar.setPointerCapture(e.pointerId);
  map.dragging.disable();
  function move(ev){
    var r = map.getContainer().getBoundingClientRect();
    swipeX = Math.min(0.98, Math.max(0.02, (ev.clientX - r.left) / r.width));
    swipeUpdate();
  }
  function up(){ bar.removeEventListener('pointermove', move); bar.removeEventListener('pointerup', up); map.dragging.enable(); }
  bar.addEventListener('pointermove', move);
  bar.addEventListener('pointerup', up);
});
map.on('move zoom resize viewreset', swipeUpdate);

// --- Side by side -----------------------------------------------------

var main = map.getContainer();
var div2 = document.createElement('div');
div2.id = 'map2';
main.parentNode.insertBefore(div2, main.nextSibling);
var map2 = null, past2 = null, ring1 = null, ring2 = null, syncing = false;

function sync(from, to){
  from.on('move', function(){
    if(syncing){ return; }
    syncing = true;
    to.setView(from.getCenter(), from.getZoom(), {animate:false});
    syncing = false;
  });
}

// A ring on each map follows the cursor on the other one.
function linkCursor(from, ring){
  from.on('mousemove', function(e){ ring.setLatLng(e.latlng).setStyle({opacity:1}); });
  from.on('mouseout', function(){ ring.setStyle({opacity:0}); });
}

function sideOn(){
  document.body.classList.add('side');
  map.invalidateSize();
  if(!map2){
    map2 = L.map(div2, {zoomControl:false, attributionControl:true});
    L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {maxZoom:19,
      attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map2);
    map2.createPane(PAST).style.zIndex = 420;
    map2.setView(map.getCenter(), map.getZoom(), {animate:false});
    sync(map, map2); sync(map2, map);
    var ringStyle = {radius:9, color:'#000', weight:2, fill:false, opacity:0, interactive:false};
    ring1 = L.circleMarker(map.getCenter(), ringStyle).addTo(map);
    ring2 = L.circleMarker(map.getCenter(), ringStyle).addTo(map2);
    linkCursor(map, ring2); linkCursor(map2, ring1);
    var tag = L.control({position:'bottomleft'});
    tag.onAdd = function(){ var d=L.DomUtil.create('div','side-tag'); d.textContent='1930s HOLC'; return d; };
    tag.addTo(map2);
  }
  map2.invalidateSize();
  map2.setView(map.getCenter(), map.getZoom(), {animate:false});
  if(past2){ map2.removeLayer(past2); }
  past2 = pastLayer(state.view, PAST, false).addTo(map2);
  tramsSync();
}

function sideOff(){
  document.body.classList.remove('side');
  map.invalidateSize();
}

// --- Streetcars ---------------------------------------------------------
// Atlanta 1928 and 1871-1920 (OpenHistoricalMap, CC0),
// Detroit Dec 1941 (rebuilt from the DSR map; trams.js). Own pane above
// both eras and never clipped, so the lines are a fixed reference that
// lines up today's map with the 1930s one.

var TRAM = 'trams';
var TRAM_COL = '#6a1b9a';
var TRAM_SRC = {
  Atlanta: 'OpenHistoricalMap (CC0), from the 1928 Atlas of Atlanta and vicinity (Emory); OpenHistoricalMap (CC0), from The Trolley Titans',
  Detroit: 'Rebuilt by eye from the Dec 1941 DSR rail map (Schramm Collection, detroittransithistory.info), traced on OpenStreetMap streets. Approximate.'
};
map.createPane(TRAM).style.zIndex = 445;

function tramHtml(p){
  var when = p.y === 'early' ? p.s+'&ndash;'+p.e : p.y;
  var h = '<b>Streetcar line, '+when+'</b> ('+esc(p.c)+')';
  if(p.n){ h += '<br>'+esc(p.n)+(p.st && p.st !== p.n ? ' line, on '+esc(p.st) : ''); }
  else if(p.st){ h += '<br>On '+esc(p.st); }
  if(p.via){ h += ' ('+esc(p.via)+')'; }
  if(p.o){ h += '<br>Operator: '+esc(p.o); }
  if(p.note){ h += '<br><small>'+esc(p.note)+'</small>'; }
  return h + '<br><small style="color:#555">'+(p.c === 'Atlanta' ? TRAM_SRC.Atlanta.split('; ')[p.y === 'early' ? 1 : 0] : TRAM_SRC[p.c])+'</small>';
}

function tramTip(p){
  var when = p.y === 'early' ? p.s+'&ndash;'+p.e : p.y;
  return 'Streetcar '+when+(p.n ? ' &middot; '+esc(p.n) : p.st ? ' &middot; '+esc(p.st) : '');
}

function tramLayer(){
  return L.geoJson(TRAMS, {pane:TRAM, renderer:L.svg({pane:TRAM}),
    style:function(f){ var early = f.properties.y === 'early';
      return {color:TRAM_COL, weight:early ? 2 : 3, opacity:early ? 0.75 : 0.95, dashArray:early ? '5 5' : null}; },
    onEachFeature:function(f,l){ l.bindPopup(tramHtml(f.properties), {maxWidth:300});
      tipOn(l, function(){ return tramTip(f.properties); }); }});
}

var trams = tramLayer().addTo(map), trams2 = null;
layer_control_097befece45624d0ea761f79e99176c6.addOverlay(trams, 'Historic streetcar lines (Atlanta 1871-1928, Detroit 1941)');

// The side-by-side map mirrors the streetcar toggle.
function tramsSync(){
  if(!map2){ return; }
  if(!trams2){ map2.createPane(TRAM).style.zIndex = 445; trams2 = tramLayer(); }
  if(map.hasLayer(trams)){ trams2.addTo(map2); } else { map2.removeLayer(trams2); }
}
map.on('overlayadd overlayremove', tramsSync);

// --- Mode switching ---------------------------------------------------

var state = {mode:MODE.OFF, view:VIEW.SCAN, opacity:0.7};
var past = null;

function apply(){
  if(past){ map.removeLayer(past); past = null; }
  clipPane('overlayPane', null); clipPane(PAST, null);
  bar.style.display = 'none';
  map.getPane(PAST).style.opacity = 1;
  sideOff();
  ui.op.style.display = state.mode === MODE.OVER && state.view !== VIEW.AREA ? 'block' : 'none';
  legendShow(state.mode !== MODE.OFF);
  window.SVI.quiet = state.mode !== MODE.OFF;
  tip.style.display = 'none';
  if(window.SVI.quiet){ map.closePopup(); }

  if(state.mode === MODE.OFF){ return; }
  if(state.mode === MODE.SIDE){ sideOn(); return; }

  past = pastLayer(state.view, PAST, state.mode === MODE.OVER && state.view === VIEW.AREA).addTo(map);
  if(state.mode === MODE.SWIPE){
    bar.style.display = 'block';
    swipeUpdate();
    return;
  }

  // Overlay: outlines stay solid; filled layers take the slider.
  if(state.view !== VIEW.AREA){ map.getPane(PAST).style.opacity = state.opacity; }
}

// --- Control panel ----------------------------------------------------

var ui = {};
var ctl = L.control({position:'topright'});
ctl.onAdd = function(){
  var d = L.DomUtil.create('div', 'leaflet-bar holc-ctl');
  d.innerHTML = '<b>Compare with 1930s redlining</b>'
    + '<div class="seg" data-k="mode">'
    + '<button data-v="off">Off</button><button data-v="swipe">Swipe</button><button data-v="side">Side by side</button><button data-v="over">Overlay</button></div>'
    + '<div class="lbl">1930s layer</div><div class="seg" data-k="view">'
    + '<button data-v="scan">Original maps</button><button data-v="area">HOLC grades</button><button data-v="tract">Tract score</button></div>'
    + '<div class="op" style="display:none"><span class="lbl">Opacity</span> <input type="range" min="0" max="100" value="70"></div>';
  L.DomEvent.disableClickPropagation(d);
  L.DomEvent.disableScrollPropagation(d);
  Array.prototype.forEach.call(d.querySelectorAll('.seg'), function(seg){
    seg.addEventListener('click', function(e){
      var v = e.target.getAttribute('data-v');
      if(!v){ return; }
      state[seg.getAttribute('data-k')] = v;
      mark(d); apply();
    });
  });
  ui.op = d.querySelector('.op');
  ui.op.querySelector('input').addEventListener('input', function(){
    state.opacity = this.value / 100;
    if(state.mode === MODE.OVER && state.view !== VIEW.AREA){ map.getPane(PAST).style.opacity = state.opacity; }
  });
  mark(d);
  return d;
};
function mark(d){
  Array.prototype.forEach.call(d.querySelectorAll('.seg button'), function(b){
    var k = b.parentNode.getAttribute('data-k');
    b.classList.toggle('on', state[k] === b.getAttribute('data-v'));
  });
}
ctl.addTo(map);

// --- Legend and About chart -------------------------------------------

var lgHolc = document.createElement('div');
lgHolc.innerHTML = '<b>1930s HOLC grade</b>' + ['A','B','C','D'].map(function(g){
  return '<div><i style="background:'+HOLC_COL[g]+'"></i>'+g+' '+HOLC_NAME[g]+'</div>'; }).join('')
  + '<small>Tract score: area-weighted grade, A=1 to D=4</small>';
var lgEl = document.getElementById('lg');
if(lgEl){ lgEl.appendChild(lgHolc); }
var lgTram = document.createElement('div');
lgTram.innerHTML = '<b>Streetcar lines</b><div><i style="background:none;border:0;border-top:3px solid '+TRAM_COL+';height:0;margin-top:5px"></i>Atlanta 1928, Detroit 1941</div>'
  + '<div><i style="background:none;border:0;border-top:2px dashed '+TRAM_COL+';height:0;margin-top:5px"></i>Atlanta 1871-1920</div>';
if(lgEl){ lgEl.appendChild(lgTram); }
function legendShow(on){ lgHolc.style.display = on ? 'block' : 'none'; }

// Mean SVI by the grade covering most of each tract, per metro.
var chart = document.getElementById('holc-chart');
if(chart){
  var h = '';
  ['Atlanta','Detroit'].forEach(function(m){
    var s = HOLC_STATS[m];
    h += '<div style="margin-top:8px"><b>'+m+'</b> ('+s.n+' tracts at least 20% graded)</div>';
    ['A','B','C','D'].forEach(function(g){
      var b = s.byGrade[g];
      if(!b[1]){ return; }
      h += '<div class="hbar"><span class="hk">'+g+' <small>n='+b[0]+'</small></span><span class="hv" style="width:'+Math.round(b[1]*100)+'%;background:'+HOLC_COL[g]+';border-color:'+HOLC_EDGE[g]+'"></span><span class="hn">'+b[1].toFixed(2)+'</span></div>';
    });
  });
  chart.innerHTML = h;
}
var rho = document.getElementById('holc-rho');
if(rho){
  var T = [['RPL_THEMES','Overall SVI'],['RPL_THEME1','Socioeconomic'],['RPL_THEME2','Household'],['RPL_THEME3','Racial and ethnic minority'],['RPL_THEME4','Housing and transport']];
  rho.innerHTML = '<tr><th>SVI part</th><th>Atlanta</th><th>Detroit</th></tr>' + T.map(function(t){
    return '<tr><td>'+t[1]+'</td><td>'+HOLC_STATS.Atlanta.rho[t[0]].toFixed(2)+'</td><td>'+HOLC_STATS.Detroit.rho[t[0]].toFixed(2)+'</td></tr>'; }).join('');
}

apply();
})();
